import java.util.*;

public class Main {
    ListNode mergeTwoLists(ListNode l1, ListNode l2) {
        List<Integer> values = new ArrayList<>();
        for (ListNode node = l1; node != null; node = node.next) values.add(node.val);   // collect every value from both lists into a plain list
        for (ListNode node = l2; node != null; node = node.next) values.add(node.val);
        Collections.sort(values);                                                          // sort the combined values from scratch
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int v : values) {
            cur.next = new ListNode(v);                                                      // rebuild a brand new linked list from the sorted values
            cur = cur.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode l1 = new ListNode(1, new ListNode(2, new ListNode(4)));
        ListNode l2 = new ListNode(1, new ListNode(3, new ListNode(4)));
        ListNode result = solution.mergeTwoLists(l1, l2);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

